import{_ as e,o as t,c as r,a3 as a}from"./chunks/framework.CDBtBf5v.js";const g=JSON.parse('{"title":"OPC UA 操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/opcua/operation.md","filePath":"guide/protocols/opcua/operation.md","lastUpdated":1794013948000}'),n={name:"guide/protocols/opcua/operation.md"};function s(c,o,p,d,l,i){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="opc-ua-操作指南" tabindex="-1">OPC UA 操作指南 <a class="header-anchor" href="#opc-ua-操作指南" aria-label="Permalink to &quot;OPC UA 操作指南&quot;">​</a></h1><h2 id="一、创建设备与配置端点" tabindex="-1">一、创建设备与配置端点 <a class="header-anchor" href="#一、创建设备与配置端点" aria-label="Permalink to &quot;一、创建设备与配置端点&quot;">​</a></h2><p>在设备管理中新增设备，协议选择 <strong>OPC UA</strong>，连接类型选择 <strong>TCP 服务端</strong> 或 <strong>TCP 客户端</strong>。</p><ul><li>服务端：填写监听 IP 和端口，在 <strong>运行状态</strong> 页配置 Endpoint 路径、命名空间 URI。</li><li>客户端：在 <strong>运行状态</strong> 页填写完整 Endpoint URL，路径必须与服务端一致。</li></ul><p>默认端口为 <code>4840</code>。同机联调时，服务端与客户端需要使用同一端点。</p><blockquote><p>📷 <strong>截图待补：OPC UA 端点与运行状态</strong> — 展示角色、Endpoint URL、连接状态和功能运行情况。 建议文件名：<code>opcua-runtime.png</code></p></blockquote><h2 id="二、配置地址空间与点表" tabindex="-1">二、配置地址空间与点表 <a class="header-anchor" href="#二、配置地址空间与点表" aria-label="Permalink to &quot;二、配置地址空间与点表&quot;">​</a></h2><p>服务端进入 <strong>地址空间 → 变量定义与模型</strong>，新增变量并配置 NodeId、BrowseName、数据类型、初始值和可写权限。也可导入模型或 Excel 点表；结构调整应先停止服务端。</p><blockquote><p>📷 <strong>截图待补：OPC UA 地址空间与变量定义</strong> — 展示 NodeId、BrowseName、数据类型、初始值及可写权限。 建议文件名：<code>opcua-address-space.png</code></p></blockquote><p>点表示例见仓库 <a href="https://github.com/600888/ems_simulate/blob/main/data/point_csv/point_sample_opcua.xlsx" target="_blank" rel="noreferrer">OPC UA Excel 模板</a>。导入时先预检，再应用导入结果。客户端测点用于映射远端 NodeId，服务端测点用于建立本地变量。</p><p>启动服务端后，在 <strong>地址空间 → 对象与变量值</strong> 中展开对象树、选择变量，查看属性、引用、当前值及数值波形；可写变量可输入当前值并执行写入。</p><blockquote><p>📷 <strong>截图待补：OPC UA 对象与实时变量值</strong> — 展开对象树并选择变量，展示属性、当前值、质量码、时间戳及波形。 建议文件名：<code>opcua-values.png</code></p></blockquote><h2 id="三、设置数据模拟" tabindex="-1">三、设置数据模拟 <a class="header-anchor" href="#三、设置数据模拟" aria-label="Permalink to &quot;三、设置数据模拟&quot;">​</a></h2><p>在 <strong>模拟规则</strong> 中选择变量，设置固定值、随机、正弦波或步进参数，保存后应用。运行中可以修改规则，暂停或恢复模拟。</p><p>外部写入策略可以选择暂停对应规则、覆盖写入值或拒绝写入，用于验证控制命令与模拟数据的交互。</p><blockquote><p>📷 <strong>截图待补：OPC UA 模拟规则</strong> — 展示固定值、随机、正弦波、步进参数，以及外部写入策略。 建议文件名：<code>opcua-simulation.png</code></p></blockquote><h2 id="四、客户端浏览与读写" tabindex="-1">四、客户端浏览与读写 <a class="header-anchor" href="#四、客户端浏览与读写" aria-label="Permalink to &quot;四、客户端浏览与读写&quot;">​</a></h2><p>启动客户端连接后，在 <strong>远端浏览</strong> 中输入起始 NodeId（例如 Objects 节点 <code>i=85</code>），浏览子节点、读取变量，或向具有写权限的变量发送值。读取结果包含数据类型、质量码与时间戳。</p><blockquote><p>📷 <strong>截图待补：OPC UA 客户端浏览与读写</strong> — 展示远端节点、读取结果、数据类型和可写变量的写入操作。 建议文件名：<code>opcua-client.png</code></p></blockquote><h2 id="五、实时订阅、历史与事件" tabindex="-1">五、实时订阅、历史与事件 <a class="header-anchor" href="#五、实时订阅、历史与事件" aria-label="Permalink to &quot;五、实时订阅、历史与事件&quot;">​</a></h2><p>进入客户端 <strong>发布订阅 → 实时数据</strong>，从左侧地址空间添加变量，设置发布间隔、采样间隔、队列、死区及监控模式，点击 <strong>开始订阅</strong>。可在表格和趋势间切换，停止单个订阅或配置自动重连。</p><blockquote><p>📷 <strong>截图待补：OPC UA 客户端实时订阅</strong> — 展示地址空间树、监控变量、发布与采样间隔，以及实时表格或趋势。 建议文件名：<code>opcua-subscription.png</code></p></blockquote><p>服务端在 <strong>发布订阅 → 历史数据</strong> 添加变量，配置保留天数和容量，启用历史存储。客户端选择具有历史读取权限的变量及时间范围后查询，分页读取结果；聚合模式取决于远端的 ReadProcessed 支持。</p><blockquote><p>📷 <strong>截图待补：OPC UA 历史数据查询</strong> — 展示查询节点、时间范围、读取模式、结果与分页操作。 建议文件名：<code>opcua-history.png</code></p></blockquote><blockquote><p>📷 <strong>截图待补：OPC UA 事件订阅</strong> — 展示事件源、严重度筛选、事件列表和详情。 建议文件名：<code>opcua-events.png</code></p></blockquote><p>事件页可添加具备 EventNotifier 能力的对象作为事件源。服务端生成事件，客户端按事件类型、严重度、关键字和返回字段订阅，并可导出 CSV。</p><p>服务端实时数据与事件发布使用 MQTT/JSON：先在 <strong>发布器设置</strong> 中配置 Broker、PublisherId 和 WriterGroup，再配置变量或事件数据集、字段和主题，保存草稿并开始发布。详细步骤见 <a href="./../../../OPCUA_PUBSUB.html">发布订阅工作区</a>。</p><blockquote><p>📷 <strong>截图待补：OPC UA MQTT/JSON 发布器设置</strong> — 展示 Broker 地址、PublisherId、WriterGroup、数据集和主题配置。 建议文件名：<code>opcua-pubsub.png</code></p></blockquote><h2 id="六、安全与诊断" tabindex="-1">六、安全与诊断 <a class="header-anchor" href="#六、安全与诊断" aria-label="Permalink to &quot;六、安全与诊断&quot;">​</a></h2><p>在 <strong>证书与安全</strong> 页发现端点、生成应用证书、管理对端信任，配置消息安全模式和身份。用户名身份要求 <code>SignAndEncrypt</code>；服务端用户支持 <code>viewer</code> 与 <code>operator</code> 角色。</p><blockquote><p>📷 <strong>截图待补：OPC UA 证书与安全</strong> — 展示消息安全模式、应用证书、对端信任及用户角色；隐藏密码和私钥。 建议文件名：<code>opcua-security.png</code></p></blockquote><p>在 <strong>会话与通信日志</strong> 查看真实服务调用及状态码。详细排查步骤见 <a href="./packet-view.html">报文与诊断查看</a>。</p>',32)])])}const h=e(n,[["render",s]]);export{g as __pageData,h as default};
